const error = $input.item.json;
const workflow = error.workflow || {};
const execution = error.execution || {};

return [{ json: {
  severity: 'CRITICAL',
  pipeline: workflow.name || 'Unknown',
  errorMessage: execution.error?.message || 'Unknown error',
  failedNode: execution.lastNodeExecuted || 'Unknown',
  timestamp: new Date().toISOString()
}}];
